def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Populate the dynamic programming table
    for i in range(N):
        for j in range(N):
            if grid_values[i][j] != 0:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + grid_values[i][j]

    # Return the maximum sum of values collected on the two paths
    return dp[N - 1][N - 1]

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.

    Example:
        >>> find_number_combinations()
        [(123, 246, 369), (124, 248, 372), ...]
    """
    combinations = []
    for i in range(1, 10):
        for j in range(1, 10):
            for k in range(1, 10):
                if i * 2 == j and i * 3 == k:
                    combinations.append((i, j, k))
    return sorted(combinations)

def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a dictionary to store the number of chatting pairs that can be separated by each aisle
    aisle_count = {}

    # Iterate over each possible position for a horizontal aisle
    for i in range(1, M):
        # Initialize the number of chatting pairs that can be separated by this aisle to 0
        aisle_count[i] = 0

        # Iterate over each chatting pair
        for pair in chatting_pairs:
            # Check if the aisle can separate this pair
            if pair[0] < i and i < pair[2]:
                aisle_count[i] += 1

    # Find the most effective position for the horizontal aisle
    horizontal_aisle = max(aisle_count, key=aisle_count.get)

    # Repeat the process for the vertical aisle
    aisle_count = {}
    for i in range(1, N):
        aisle_count[i] = 0
        for pair in chatting_pairs:
            if pair[1] < i and i < pair[3]:
                aisle_count[i] += 1
    vertical_aisle = max(aisle_count, key=aisle_count.get)

    return (horizontal_aisle, vertical_aisle)

