def max_energy(beads):
    # Initialize a dictionary to store the maximum energy for each prefix of the necklace
    max_energies = {0: 0}

    # Iterate over the beads and calculate the maximum energy for each prefix
    for i in range(len(beads)):
        # The maximum energy for the current prefix is the maximum of the energy from the previous prefix and the energy from merging the current bead with the previous bead
        max_energies[i] = max(max_energies[i - 1], beads[i] * beads[(i - 1) % len(beads)] * beads[(i + 1) % len(beads)])

    # Return the maximum energy for the entire necklace
    return max_energies[len(beads) - 1]

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort the applicants based on their test scores in descending order
    sorted_applicants = sorted(applicants, key=lambda x: x[1], reverse=True)

    # Calculate the interview score cutoff based on 150% of the planned number of recruits, rounded down
    interview_score_cutoff = int(m * 1.5)

    # Select the qualified applicants based on their test scores and registration numbers
    qualified_applicants = []
